 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec3,
  texture,
  mix,
  smoothstep,
  mul,
  add,
  sub,
  fract,
  sin,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Box3, Vector3, DoubleSide, Color } = ctx.THREE;

  const visualSpec = config.intent?.visualSpec ?? config.visual ?? config;
  const colors = visualSpec?.colors ?? {};
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((i) => i.role === 'headline') ?? items[0] ?? { text: 'Get started', typography: { fontSize: 42 } };

  const ink = new Color(colors.ink ?? '#16161d');
  const surface = new Color(colors.surface ?? '#0b0b10');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const paper = new Color(colors.paper ?? '#e8ecf2');

  const atlas = config.atlasRegion ?? {};
  const [_, __, aw, ah] = Array.isArray(atlas.sourceRect)
    ? atlas.sourceRect
    : [0, 0, 512, 320];
  const pxToUnit = 0.0009375;
  const planeW = aw * pxToUnit;
  const planeH = ah * pxToUnit;

  const group = new Group();
  group.name = config.id ?? 'home-cta';

  const geometry = new PlaneGeometry(planeW, planeH);
  const material = new MeshBasicNodeMaterial({ side: DoubleSide });
  const surfaceMesh = new Mesh(geometry, material);
  surfaceMesh.name = 'cta-surface';
  group.add(surfaceMesh);

  material.colorNode = vec3(surface.r, surface.g, surface.b);

  let loadedMap = null;
  const timelines = [];

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedMap = tex;

      const u = uv();
      const grad = smoothstep(0.0, 1.0, u.y);
      const base = mix(
        vec3(surface.r, surface.g, surface.b),
        vec3(ink.r, ink.g, ink.b),
        grad
      );

      const accentBand = smoothstep(0.05, 0.0, u.y);
      const tinted = mix(
        base,
        vec3(accent.r, accent.g, accent.b),
        mul(accentBand, 0.35)
      );

      const metal = texture(tex, u);
      const metalValue = mix(0.78, 1.06, metal.r);
      const shaded = mul(tinted, vec3(metalValue));

      const hash = fract(
        mul(
          sin(add(mul(u.x, 12.9898), mul(u.y, 78.233))),
          43758.5453
        )
      );
      const grain = mul(sub(hash, 0.5), 0.07);
      const final = add(shaded, vec3(grain));

      material.colorNode = final;
      material.needsUpdate = true;
    });
  }

  const text = ctx.fontAtlas.createText(headline.text, {
    fontSize: headline.typography?.fontSize ?? 42,
    color: `#${paper.getHexString()}`,
    align: 'center',
  });
  text.name = 'cta-text';
  group.add(text);

  const box = new Box3().setFromObject(text);
  const size = new Vector3();
  box.getSize(size);

  const maxW = planeW * 0.82;
  const scale = size.x > maxW ? maxW / size.x : 1;
  text.scale.setScalar(scale);

  const scaledBox = new Box3().setFromObject(text);
  const center = new Vector3();
  scaledBox.getCenter(center);
  text.position.set(-center.x, -center.y, 0.05);

  const cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    if (loadedMap) {
      loadedMap.dispose();
      loadedMap = null;
    }
    geometry.dispose();
    material.dispose();

    text.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => m.dispose());
        } else {
          o.material.dispose();
        }
      }
    });
  };

  group.userData.handlers = {};
  group.userData.cleanup = cleanup;
  group.userData.primitiveRefs = [];

  return group;
}
